const express = require('express');
const app = express();

app.use(express.json());

function tokenizeRule(expr) {
  const tokens = [];
  let i = 0;

  while (i < expr.length) {
    const ch = expr[i];

    if (/\s/.test(ch)) {
      i += 1;
      continue;
    }

    const three = expr.slice(i, i + 3);
    if (three === '===' || three === '!==') {
      tokens.push({ type: 'op', value: three });
      i += 3;
      continue;
    }

    const two = expr.slice(i, i + 2);
    if (['&&', '||', '>=', '<=', '==', '!='].includes(two)) {
      tokens.push({ type: 'op', value: two });
      i += 2;
      continue;
    }

    if ('()!.<>+-*/%'.includes(ch)) {
      tokens.push({ type: ch === '(' || ch === ')' || ch === '.' ? 'punc' : 'op', value: ch });
      i += 1;
      continue;
    }

    if (ch === '"' || ch === "'") {
      const quote = ch;
      let value = '';
      i += 1;

      while (i < expr.length) {
        if (expr[i] === '\\') {
          if (i + 1 >= expr.length) {
            throw new Error('Invalid string escape');
          }
          const escaped = expr[i + 1];
          const escapes = { n: '\n', r: '\r', t: '\t', b: '\b', f: '\f', v: '\v', '0': '\0' };
          value += Object.prototype.hasOwnProperty.call(escapes, escaped) ? escapes[escaped] : escaped;
          i += 2;
          continue;
        }

        if (expr[i] === quote) {
          i += 1;
          tokens.push({ type: 'literal', value });
          value = null;
          break;
        }

        value += expr[i];
        i += 1;
      }

      if (value !== null) {
        throw new Error('Unterminated string literal');
      }
      continue;
    }

    if (/\d/.test(ch) || (ch === '.' && /\d/.test(expr[i + 1]))) {
      const match = expr.slice(i).match(/^(?:\d+\.?\d*|\.\d+)(?:e[+-]?\d+)?/i);
      if (!match) {
        throw new Error('Invalid number literal');
      }
      tokens.push({ type: 'literal', value: Number(match[0]) });
      i += match[0].length;
      continue;
    }

    if (/[A-Za-z_$]/.test(ch)) {
      const match = expr.slice(i).match(/^[A-Za-z_$][\w$]*/);
      const word = match[0];
      if (word === 'true') tokens.push({ type: 'literal', value: true });
      else if (word === 'false') tokens.push({ type: 'literal', value: false });
      else if (word === 'null') tokens.push({ type: 'literal', value: null });
      else if (word === 'undefined') tokens.push({ type: 'literal', value: undefined });
      else tokens.push({ type: 'identifier', value: word });
      i += word.length;
      continue;
    }

    throw new Error(`Unexpected character: ${ch}`);
  }

  tokens.push({ type: 'eof' });
  return tokens;
}

function readSafeProperty(target, key) {
  if (target == null) {
    return undefined;
  }

  // Avoid prototype traversal and constructor gadgets. Rule expressions only need
  // request/context data, not access to inherited JavaScript internals.
  if (['__proto__', 'prototype', 'constructor'].includes(key)) {
    return undefined;
  }

  if (Object.prototype.hasOwnProperty.call(Object(target), key)) {
    return Object(target)[key];
  }

  return undefined;
}

function evaluateSafeExpression(expr, scope) {
  const tokens = tokenizeRule(expr);
  let pos = 0;

  function peek() {
    return tokens[pos];
  }

  function consume(value) {
    if (peek().value === value) {
      pos += 1;
      return true;
    }
    return false;
  }

  function expect(value) {
    if (!consume(value)) {
      throw new Error(`Expected '${value}'`);
    }
  }

  function parsePrimary() {
    const token = peek();

    if (token.type === 'literal') {
      pos += 1;
      return token.value;
    }

    if (token.type === 'identifier') {
      pos += 1;
      if (!Object.prototype.hasOwnProperty.call(scope, token.value)) {
        throw new Error(`Unknown identifier: ${token.value}`);
      }

      let value = scope[token.value];
      while (consume('.')) {
        const prop = peek();
        if (prop.type !== 'identifier') {
          throw new Error('Expected property name after dot');
        }
        pos += 1;
        value = readSafeProperty(value, prop.value);
      }
      return value;
    }

    if (consume('(')) {
      const value = parseOr();
      expect(')');
      return value;
    }

    throw new Error('Expected value');
  }

  function parseUnary() {
    if (consume('!')) return !parseUnary();
    if (consume('-')) return -parseUnary();
    if (consume('+')) return +parseUnary();
    return parsePrimary();
  }

  function parseMultiplicative() {
    let left = parseUnary();
    while (['*', '/', '%'].includes(peek().value)) {
      const op = peek().value;
      pos += 1;
      const right = parseUnary();
      if (op === '*') left *= right;
      else if (op === '/') left /= right;
      else left %= right;
    }
    return left;
  }

