const express = require('express');
const app = express();

app.use(express.json());

const FORBIDDEN_PROPERTIES = new Set(['__proto__', 'prototype', 'constructor']);

function tokenize(input) {
  const tokens = [];
  let i = 0;

  while (i < input.length) {
    const ch = input[i];

    if (/\s/.test(ch)) {
      i += 1;
      continue;
    }

    const three = input.slice(i, i + 3);
    if (three === '===' || three === '!==') {
      tokens.push({ type: 'operator', value: three });
      i += 3;
      continue;
    }

    const two = input.slice(i, i + 2);
    if (['>=', '<=', '&&', '||', '==', '!='].includes(two)) {
      tokens.push({ type: 'operator', value: two });
      i += 2;
      continue;
    }

    if ('()+-*/%<>!.[]'.includes(ch)) {
      tokens.push({ type: ch === '.' || ch === '(' || ch === ')' || ch === '[' || ch === ']' ? 'punctuation' : 'operator', value: ch });
      i += 1;
      continue;
    }

    if (ch === '"' || ch === "'") {
      const quote = ch;
      let value = '';
      i += 1;
      while (i < input.length) {
        if (input[i] === quote) break;
        if (input[i] === '\\') {
          i += 1;
          if (i >= input.length) throw new Error('Unterminated string literal');
          const escapes = { n: '\n', r: '\r', t: '\t', b: '\b', f: '\f', v: '\v', '\\': '\\', '"': '"', "'": "'" };
          value += Object.prototype.hasOwnProperty.call(escapes, input[i]) ? escapes[input[i]] : input[i];
          i += 1;
          continue;
        }
        value += input[i];
        i += 1;
      }
      if (input[i] !== quote) throw new Error('Unterminated string literal');
      i += 1;
      tokens.push({ type: 'literal', value });
      continue;
    }

    if (/\d/.test(ch) || (ch === '.' && /\d/.test(input[i + 1]))) {
      const match = input.slice(i).match(/^(?:\d+\.?\d*|\.\d+)(?:e[+-]?\d+)?/i);
      if (!match) throw new Error('Invalid number literal');
      tokens.push({ type: 'literal', value: Number(match[0]) });
      i += match[0].length;
      continue;
    }

    if (/[A-Za-z_$]/.test(ch)) {
      const match = input.slice(i).match(/^[A-Za-z_$][A-Za-z0-9_$]*/);
      tokens.push({ type: 'identifier', value: match[0] });
      i += match[0].length;
      continue;
    }

    throw new Error(`Unexpected token '${ch}'`);
  }

  tokens.push({ type: 'eof', value: '' });
  return tokens;
}

class RuleParser {
  constructor(tokens) {
    this.tokens = tokens;
    this.pos = 0;
  }

  current() {
    return this.tokens[this.pos];
  }

  match(value) {
    if (this.current().value === value) {
      this.pos += 1;
      return true;
    }
    return false;
  }

  expect(value) {
    if (!this.match(value)) throw new Error(`Expected '${value}'`);
  }

  parse() {
    const ast = this.parseLogicalOr();
    if (this.current().type !== 'eof') throw new Error(`Unexpected token '${this.current().value}'`);
    return ast;
  }

  parseLogicalOr() {
    let node = this.parseLogicalAnd();
    while (this.match('||')) {
      node = { type: 'LogicalExpression', operator: '||', left: node, right: this.parseLogicalAnd() };
    }
    return node;
  }

  parseLogicalAnd() {
    let node = this.parseEquality();
    while (this.match('&&')) {
      node = { type: 'LogicalExpression', operator: '&&', left: node, right: this.parseEquality() };
    }
    return node;
  }

  parseEquality() {
    let node = this.parseRelational();
    while (['===', '!==', '==', '!='].includes(this.current().value)) {
      const operator = this.current().value;
      this.pos += 1;
      node = { type: 'BinaryExpression', operator, left: node, right: this.parseRelational() };
    }
    return node;
  }

  parseRelational() {
    let node = this.parseAdditive();
    while (['>', '>=', '<', '<='].includes(this.current().value)) {
      const operator = this.current().value;
      this.pos += 1;
      node = { type: 'BinaryExpression', operator, left: node, right: this.parseAdditive() };
    }
    return node;
  }

  parseAdditive() {
    let node = this.parseMultiplicative();
    while (['+', '-'].includes(this.current().value)) {
      const operator = this.current().value;
      this.pos += 1;
      node = { type: 'BinaryExpression', operator, left: node, right: this.parseMultiplicative() };
    }
    return node;
  }

  parseMultiplicative() {
    let node = this.parseUnary();
    while (['*', '/', '%'].includes(this.current().value)) {
      const operator = this.current().value;
      this.pos += 1;
      node = { type: 'BinaryExpression', operator, left: node, right: this.parseUnary() };
    }
    return node;
  }

  parseUnary() {
    if (['!', '+', '-'].includes(this.current().value)) {
      const operator = this.current().value;
      this.pos += 1;
      return { type: 'UnaryExpression', operator, argument: this.parseUnary() };
    }
    return this.parseMember();
  }

  parseMember() {
    let node = this.parsePrimary();

    while (true) {
      if (this.match('.')) {
        const token = this.current();
        if (token.type !== 'identifier') throw new Error('Expected property name');
        this.pos += 1;
        node = { type: 'MemberExpression', object: node, property: { type: 'Literal', value: token.value }, computed: false };
        continue;
      }

      if (this.match('[')) {
        const property = this.parseLogicalOr();
        this.expect(']');
        node = { type: 'MemberExpression', object: node, property, computed: true };
        continue;
      }

      return node;
    }
  }

  parsePrimary() {
    const token = this.current();

    if (token.type === 'literal') {
      this.pos += 1;
      return { type: 'Literal', value: token.value };
    }

    if (token.type === 'identifier') {
      this.pos += 1;
      if (token.value === 'true') return { type: 'Literal', value: true };
      if (token.value === 'false') return { type: 'Literal', value: false };
      if (token.value === 'null') return { type: 'Literal', value: null };
      if (token.value === 'undefined') return { type: 'Literal', value: undefined };
      return { type: 'Identifier', name: token.value };
    }

    if (this.match('(')) {
      const node = this.parseLogicalOr();
      this.expect(')');
      return node;
    }

    throw new Error(`Unexpected token '${token.value}'`);
  }
}

function evaluateAst(node, scope) {
  switch (node.type) {
    case 'Literal':
      return node.value;
    case 'Identifier':
      if (node.name !== 'ctx') throw new Error(`Unknown identifier '${node.name}'`);
      return scope.ctx;
    case 'MemberExpression': {
      const object = evaluateAst(node.object, scope);
      const property = evaluateAst(node.property, scope);
      if (typeof property !== 'string' && typeof property !== 'number') {
        throw new Error('Property name must be a string or number');
      }
      const key = String(property);
      if (FORBIDDEN_PROPERTIES.has(key)) throw new Error(`Access to property '${key}' is not allowed`);
      if (object === null || object === undefined) return undefined;
      if (typeof object !== 'object' && typeof object !== 'string' && !Array.isArray(object)) return undefined;
      return object[key];
    }
    case 'UnaryExpression': {
      const value = evaluateAst(node.argument, scope);
      if (node.operator === '!') return !value;
      if (node.operator === '+') return +value;
      if (node.operator === '-') return -value;
      throw new Error(`Unsupported operator '${node.operator}'`);
    }
    case 'LogicalExpression': {
      if (node.operator === '&&') {
        const left = evaluateAst(node.left, scope);
        return left && evaluateAst(node.right, scope);
      }
      if (node.operator === '||') {
        const left = evaluateAst(node.left, scope);
        return left || evaluateAst(node.right, scope);
      }
      throw new Error(`Unsupported operator '${node.operator}'`);
    }
    case 'BinaryExpression': {
      const left = evaluateAst(node.left, scope);
      const right = evaluateAst(node.right, scope);
      switch (node.operator) {
        case '===': return left === right;
        case '!==': return left !== right;
        case '==': return left == right; // eslint-disable-line eqeqeq
        case '!=': return left != right; // eslint-disable-line eqeqeq
        case '>': return left > right;
        case '>=': return left >= right;
        case '<': return left < right;
        case '<=': return left <= right;
        case '+': return left + right;
        case '-': return left - right;
        case '*': return left * right;
        case '/': return left / right;
        case '%': return left % right;
        default: throw new Error(`Unsupported operator '${node.operator}'`);
      }
    }
    default:
      throw new Error(`Unsupported expression type '${node.type}'`);
  }
}

function evalRule(req) {
  if (!req.body || typeof req.body.rule !== 'string') {
    throw new Error('Request body must include a rule string');
  }

  const ast = new RuleParser(tokenize(req.body.rule)).parse();
  return evaluateAst(ast, { ctx: req.body.context || {} });
}

