        } else {
          value += input[i];
        }
        i += 1;
      }
      if (input[i] !== quote) throw new RuleSyntaxError('Unterminated string literal');
      i += 1;
      tokens.push({ type: 'literal', value });
      continue;
    }

    if (/\d/.test(ch) || (ch === '.' && /\d/.test(input[i + 1]))) {
      const start = i;
      i += 1;
      while (i < input.length && /[\d.]/.test(input[i])) i += 1;
      const value = Number(input.slice(start, i));
      if (!Number.isFinite(value)) throw new RuleSyntaxError('Invalid number literal');
      tokens.push({ type: 'literal', value });
      continue;
    }

    if (/[A-Za-z_$]/.test(ch)) {
      const start = i;
      i += 1;
      while (i < input.length && /[A-Za-z0-9_$]/.test(input[i])) i += 1;
      const ident = input.slice(start, i);
      if (ident === 'true') tokens.push({ type: 'literal', value: true });
      else if (ident === 'false') tokens.push({ type: 'literal', value: false });
      else if (ident === 'null') tokens.push({ type: 'literal', value: null });
      else if (ident === 'undefined') tokens.push({ type: 'literal', value: undefined });
      else tokens.push({ type: 'identifier', value: ident });
      continue;
    }

