    if (object == null) return undefined;
    if (['__proto__', 'prototype', 'constructor'].includes(String(property))) return undefined;
    return object[property];
  };

  const parseExpression = () => parseOr();

  const parseOr = () => {
    let left = parseAnd();
    while (consume('op', '||')) {
      const right = parseAnd();
      left = left || right;
    }
    return left;
  };

  const parseAnd = () => {
    let left = parseEquality();
    while (consume('op', '&&')) {
      const right = parseEquality();
      left = left && right;
    }
    return left;
