      else if (op === '/') left /= right;
      else left %= right;
    }
    return left;
  };

  const parseUnary = () => {
    if (consume('op', '!')) return !parseUnary();
    if (consume('op', '-')) return -parseUnary();
    if (consume('op', '+')) return +parseUnary();
    return parsePrimary();
  };

  const parsePrimary = () => {
    let value;
    const token = peek();

    if (consume('(', '(')) {
      value = parseExpression();
      expect(')', ')');
