      }
    }
  };

  const result = parseExpression();
  if (peek().type !== 'eof') throw new RuleSyntaxError(`Unexpected token: ${peek().value}`);
  return result;
}

function evalRule(req) {
  const safeReq = {
    method: req.method,
    path: req.path,
    query: req.query,
    headers: req.headers,
    body: req.body,
  };

  return evaluateRuleExpression(req.body.rule, {
    ctx: req.body.context || {},
