function tokenize(input) {
  const tokens = [];
  let i = 0;

  while (i < input.length) {
    const ch = input[i];

    if (/\s/.test(ch)) {
      i += 1;
      continue;
    }

    const three = input.slice(i, i + 3);
    if (three === '===' || three === '!==') {
      tokens.push({ type: 'operator', value: three });
      i += 3;
      continue;
    }

    const two = input.slice(i, i + 2);
    if (['>=', '<=', '==', '!=', '&&', '||'].includes(two)) {
      tokens.push({ type: 'operator', value: two });
      i += 2;
      continue;
    }

    if (['>', '<', '+', '-', '*', '/', '%', '!', '(', ')', '.'].includes(ch)) {
      tokens.push({ type: ch === '(' || ch === ')' || ch === '.' ? 'punctuation' : 'operator', value: ch });
      i += 1;
      continue;
    }

    if (ch === '"' || ch === "'") {
      const quote = ch;
      let value = '';
      i += 1;
      while (i < input.length) {
        if (input[i] === '\\') {
          const next = input[i + 1];
          const escapes = { n: '\n', r: '\r', t: '\t', b: '\b', f: '\f', '\\': '\\', '"': '"', "'": "'" };
          value += Object.prototype.hasOwnProperty.call(escapes, next) ? escapes[next] : next;
          i += 2;
          continue;
        }
        if (input[i] === quote) break;
        value += input[i];
        i += 1;
      }
      if (input[i] !== quote) throw new Error('Unterminated string literal');
      i += 1;
      tokens.push({ type: 'literal', value });
      continue;
    }

    if (/\d/.test(ch)) {
      const start = i;
      while (i < input.length && /[\d.]/.test(input[i])) i += 1;
      const raw = input.slice(start, i);
      const value = Number(raw);
      if (!Number.isFinite(value)) throw new Error(`Invalid number literal: ${raw}`);
      tokens.push({ type: 'literal', value });
      continue;
    }

    if (/[A-Za-z_$]/.test(ch)) {
      const start = i;
      while (i < input.length && /[A-Za-z0-9_$]/.test(input[i])) i += 1;
      const value = input.slice(start, i);
      if (value === 'true') tokens.push({ type: 'literal', value: true });
      else if (value === 'false') tokens.push({ type: 'literal', value: false });
      else if (value === 'null') tokens.push({ type: 'literal', value: null });
      else if (value === 'undefined') tokens.push({ type: 'literal', value: undefined });
      else tokens.push({ type: 'identifier', value });
      continue;
    }

    throw new Error(`Unexpected character: ${ch}`);
  }

  return tokens;
}

function createParser(tokens, context) {
  let current = 0;

  const peek = () => tokens[current];
  const match = (...values) => {
    const token = peek();
    if (token && values.includes(token.value)) {
      current += 1;
      return token;
    }
    return null;
  };
  const consume = (value, message) => {
