class RuleSyntaxError extends Error {}

function tokenize(input) {
  const tokens = [];
  let i = 0;

  while (i < input.length) {
    const ch = input[i];

    if (/\s/.test(ch)) {
      i += 1;
      continue;
    }

    const three = input.slice(i, i + 3);
    if (three === '===' || three === '!==') {
      tokens.push({ type: 'operator', value: three });
      i += 3;
      continue;
    }

    const two = input.slice(i, i + 2);
    if (['>=', '<=', '==', '!=', '&&', '||'].includes(two)) {
      tokens.push({ type: 'operator', value: two });
      i += 2;
      continue;
    }

    if (['>', '<', '!', '(', ')', '.', '[', ']'].includes(ch)) {
      tokens.push({ type: ch, value: ch });
      i += 1;
      continue;
    }

    if (ch === '"' || ch === "'") {
      const quote = ch;
      let value = '';
      i += 1;

      while (i < input.length) {
        const current = input[i];
        if (current === quote) {
          i += 1;
          tokens.push({ type: 'literal', value });
          break;
        }
        if (current === '\\') {
          const next = input[i + 1];
          const escapes = { n: '\n', r: '\r', t: '\t', b: '\b', f: '\f', '\\': '\\', '"': '"', "'": "'" };
          if (next === undefined) throw new RuleSyntaxError('Unterminated string literal');
          value += Object.prototype.hasOwnProperty.call(escapes, next) ? escapes[next] : next;
          i += 2;
          continue;
        }
        value += current;
        i += 1;
      }

      if (tokens[tokens.length - 1]?.value !== value) {
        throw new RuleSyntaxError('Unterminated string literal');
      }
      continue;
    }

    if (/\d/.test(ch)) {
      const start = i;
      i += 1;
      while (i < input.length && /[\d.]/.test(input[i])) i += 1;
      const raw = input.slice(start, i);
      if (!/^\d+(\.\d+)?$/.test(raw)) throw new RuleSyntaxError(`Invalid number: ${raw}`);
      tokens.push({ type: 'literal', value: Number(raw) });
      continue;
    }

    if (/[A-Za-z_$]/.test(ch)) {
      const start = i;
      i += 1;
      while (i < input.length && /[A-Za-z0-9_$]/.test(input[i])) i += 1;
      const word = input.slice(start, i);
      if (word === 'true') tokens.push({ type: 'literal', value: true });
      else if (word === 'false') tokens.push({ type: 'literal', value: false });
      else if (word === 'null') tokens.push({ type: 'literal', value: null });
      else if (word === 'undefined') tokens.push({ type: 'literal', value: undefined });
      else tokens.push({ type: 'identifier', value: word });
      continue;
    }

    throw new RuleSyntaxError(`Unexpected character: ${ch}`);
  }

  tokens.push({ type: 'eof', value: '<eof>' });
