function evaluateRuleExpression(expr, scope) {
  if (typeof expr !== 'string' || expr.trim() === '') {
    throw new RuleSyntaxError('rule must be a non-empty string');
  }

  const tokens = tokenize(expr);
  let pos = 0;

  function peek() {
    return tokens[pos];
  }

  function match(type, value) {
    const token = peek();
    if (token.type === type && (value === undefined || token.value === value)) {
      pos += 1;
      return token;
    }
    return null;
  }

  function expect(type, value) {
    const token = match(type, value);
    if (!token) throw new RuleSyntaxError(`Expected ${value || type}`);
    return token;
  }

  function parseExpression() {
    return parseOr();
  }

  function parseOr() {
    let left = parseAnd();
    while (match('operator', '||')) {
      left = left || parseAnd();
    }
    return left;
  }

  function parseAnd() {
    let left = parseEquality();
    while (match('operator', '&&')) {
      left = left && parseEquality();
    }
    return left;
  }

  function parseEquality() {
    let left = parseComparison();
    for (;;) {
      if (match('operator', '===')) left = left === parseComparison();
      else if (match('operator', '!==')) left = left !== parseComparison();
