      else if (match('operator', '!=')) left = left != parseComparison(); // eslint-disable-line eqeqeq
      else return left;
    }
  }

  function parseComparison() {
    let left = parseUnary();
    for (;;) {
      if (match('operator', '>=')) left = left >= parseUnary();
      else if (match('operator', '<=')) left = left <= parseUnary();
      else if (match('>', '>')) left = left > parseUnary();
      else if (match('<', '<')) left = left < parseUnary();
